//! 🧪️ Actual original writer columns and payload retain source ownership through each native frontier.
use super::*;
use semio_framework_value::{RetainedCloneGrant as Grant,RetainedCloneProgress as Progress,RetainedCloneStep as Step,retirement::controlled::ControlledRetirement};
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_tick_writer_admission_preserves_native_sources_all_receipts_and_payload_copy(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=Grant{maximum_items:p[0].as_u64().unwrap()as usize,maximum_copy_bytes:p[1].as_u64().unwrap()as usize,maximum_capacity_bytes:p[2].as_u64().unwrap()as usize,maximum_release_bytes:p[3].as_u64().unwrap()as usize,maximum_depth:p[4].as_u64().unwrap()as usize};let identity=ToolRunIdentity::new(ToolRunId{app_instance_id:7,run:11},[17;32]);let mut writer=ToolRunTickWriter::new(identity);let mut born=0;let mut released=0;let mut entity=Some(17);let mut trace=Some(ToolRunTraceOp::Upsert{key:17,verdict:ToolRunVerdict::Success,reason:1,subject:ToolRunTraceSubject::Entity{entity:17}});let(ring,heap)=observe(ToolRunStepRing::new);assert_eq!(heap,(0,0));assert_eq!(ring.steps.capacity(),0);let mut progress=Some(ToolRunProgress{identity,sequence:0,state:ToolRunState::Running,stage:0,completed:17,total:Some(18),counters:Vec::new(),units_per_second:0.0,conflicts:0,steps:ring});let mut counter=Some(ToolRunCounter{counter:0,value:7});let source=[17u8,0,0,0];let source_pointer=source.as_ptr();let mut cursor=0;
 for phase in 0..5{let mut turns=0;loop{for denied in[Grant{maximum_items:0,..grant},Grant{maximum_depth:0,..grant}]{let before=cursor;let(step,heap)=observe(||match phase{0=>writer.admit_original_entity(&mut entity,denied),1=>writer.admit_original_trace(&mut trace,denied),2=>ToolRunTickWriter::admit_original_progress_counter(progress.as_mut().unwrap(),&mut counter,denied),3=>writer.admit_original_progress(&mut progress,denied),_=>writer.admit_original_payload(&source,&mut cursor,denied)}.unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),Progress::default());assert_eq!(cursor,before);}let(step,heap)=observe(||match phase{0=>writer.admit_original_entity(&mut entity,grant),1=>writer.admit_original_trace(&mut trace,grant),2=>ToolRunTickWriter::admit_original_progress_counter(progress.as_mut().unwrap(),&mut counter,grant),3=>writer.admit_original_progress(&mut progress,grant),_=>writer.admit_original_payload(&source,&mut cursor,grant)}.unwrap());let actual=step.progress();assert!(actual.fits(grant));assert_eq!(heap,(actual.retained_capacity_bytes,actual.released_bytes));assert_eq!(actual.copied_bytes,if phase==4&&cursor>0{4}else{0});born+=heap.0;released+=heap.1;turns+=1;assert!(turns<10);if matches!(step,Step::Complete(_)){break}}eprintln!("[DEBUG] actual original writer admission phase={phase} turns={turns} original5axes metadata0 source={source_pointer:p}");}
 assert_eq!(writer.append_entities,[17]);assert_eq!(writer.page_ops.len(),1);assert_eq!(writer.progress.as_ref().unwrap().counters[0].value,7);assert_eq!(writer.payload.as_deref(),Some(source.as_slice()));assert_eq!(cursor,4);let pointer=writer.payload.as_ref().unwrap().as_ptr();let substitute=[17u8,0,0,0];let(result,heap)=observe(||writer.admit_original_payload(&substitute,&mut cursor,grant));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(writer.payload.as_ref().unwrap().as_ptr(),pointer);
 let(mut owner,heap)=observe(||ControlledRetirement::new(writer).ok().unwrap());born+=heap.0;released+=heap.1;while !owner.terminal_is_empty(){let(step,heap)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;}assert_eq!(born,released);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original writer entity/trace/counter/progress/nativePayload4 allReceipts physical={released} terminalDrop0");
}
